  modal('Your cloud workspace',`<p>Signed in as <strong>${escape(cloud.user.email||'your account')}</strong>.</p><div class="cloud-summary"><h3>${cloud.dirty?'Your current changes need saving.':cloud.savedAt?'Your workspace has been saved.':'Choose when to save your work.'}</h3><p class="small-print">${cloud.savedAt?'Last cloud save: '+escape(new Date(cloud.savedAt).toLocaleString())+'. ':''}Saving uploads the current prospect list, shortlist, drafts, business brief, and activity to your private workspace. It does not connect discovery or sending.</p></div>`,`<button class="button secondary" data-action="cloud-load">Load saved workspace</button><button class="button primary" data-action="cloud-save">Save current workspace</button><button class="link-button" data-action="cloud-logout">Sign out</button>`);
