 return `<section class="ai-workspace"><div class="ai-main"><div class="ai-toolbar"><span class="ai-status ${ready?'ready':''}"><span></span>${status}</span><div class="ai-toolbar-actions">${assistantState.model?`<span class="ai-model">${escape(assistantState.model)}</span>`:''}<button class="link-button" data-action="ai-refresh">Check connection</button>${assistantState.messages.length?'<button class="link-button" data-action="ai-clear">New conversation</button>':''}</div></div><div id="ai-transcript" class="ai-transcript" role="log" aria-label="Your conversation with Pull AI" aria-live="polite">${assistantState.messages.length?assistantState.messages.map(m=>`<article class="ai-message ${m.role}"><span class="ai-message-label">${m.role==='user'?'You':'Pull AI'}</span><p>${escape(m.content)}</p></article>`).join(''):welcome}${assistantState.busy?'<div class="ai-thinking" role="status"><span></span><span></span><span></span>Working with your context…</div>':''}</div>${assistantState.error?`<div class="ai-error" role="alert"><p>${escape(assistantState.error)}</p>${assistantState.lastMessage?'<button class="link-button" data-action="ai-retry">Retry this request</button>':''}</div>`:''}<form id="ai-form" class="ai-composer"><label class="sr-only" for="ai-message">Ask Pull AI</label><textarea id="ai-message" name="message" rows="2" maxlength="5000" placeholder="Tell Pull what you want to work on…" ${assistantState.busy?'disabled':''}>${escape(assistantState.draft)}</textarea><div class="ai-composer-bottom"><span>Suggestions stay yours to review.</span><button class="button primary" type="submit" ${!ready||assistantState.busy?'disabled':''}>${assistantState.busy?'Thinking…':'Ask Pull'}${uiIcon('arrow')}</button></div></form><div class="ai-boundary">${!configured&&assistantState.configured!==null?'A model provider has not been configured. Your Focus workspace works while setup is completed.':!cloud.user?'Sign in to use your private AI workspace.':!cloud.verified?'Verify your account connection before sending a question.':'When you send a question, the model receives the context selected here. Nothing is sent to prospects.'}${!cloud.user?'<button class="link-button" data-action="account">Sign in</button>':''}</div></div><aside class="ai-context"><div class="ai-context-head"><span class="section-kicker">WORKING WITH YOU</span><h3>Your context</h3>${uiIcon('brief')}</div><div class="ai-context-business"><span>${state.context==='company'?'Company workspace':'Personal workspace'}</span><strong>${escape(state.identity)}</strong><p>${state.offer?escape(state.offer):'Add your offer so Pull understands who you help.'}</p><button class="link-button" data-action="workspace">Edit your brief</button></div><dl class="ai-context-details"><div><dt>Market</dt><dd>${escape(state.rules.countries.trim()||'Worldwide')}</dd></div><div><dt>Audience</dt><dd>${escape(state.rules.roles||'Not defined')}</dd></div><div><dt>Reviewed prospects</dt><dd>${state.shortlist.length}</dd></div></dl><label class="ai-context-choice"><input id="ai-share-context" type="checkbox" ${assistantState.shareContext?'checked':''}><span>Use this workspace context</span></label><p class="ai-context-note">Includes your brief, audience rules, and up to 8 reviewed prospects. Emails and account tokens are excluded. This conversation stays in this tab.</p><div class="ai-principle">${uiIcon('shield')}<p>AI suggests.<br><strong>You decide.</strong><small>It cannot change your audience, invent a prospect, or send a message from this conversation.</small></p></div><button class="ai-own-agent" data-action="agents">Bring your own agent ${uiIcon('arrow')}</button></aside></section>`;
